167	/* ─── Utilities ─────────────────────────────────────────────────────────────── */
168	@layer utilities {
169	  /* Webflow .paragraph / .paragraph-regular */
170	  .paragraph {
171	    font-size: 16px;
172	    line-height: 28px;
173	    color: #2b2b2b;
